## 4. API Route Patterns

### GET Route Template

```typescript
// src/app/api/products/route.ts

import { NextRequest, NextResponse } from 'next/server';
import { fetchProducts } from '@/services/productServices';

export async function GET(request: NextRequest) {
  try {
    // Extract query parameters
    const searchParams = request.nextUrl.searchParams;
    const page = parseInt(searchParams.get('page') || '1');
    const perPage = parseInt(searchParams.get('per_page') || '12');
    const category = searchParams.get('category') || undefined;

    // Validate parameters
    if (page < 1 || perPage < 1 || perPage > 100) {
      return NextResponse.json(
        { error: 'Invalid pagination parameters' },
        { status: 400 }
      );
    }

    // Call service layer
    const result = await fetchProducts(page, perPage, category);

    // Return response with cache headers
    return NextResponse.json(result, {
      headers: {
        'Cache-Control': 'public, s-maxage=3600, stale-while-revalidate=86400',
      },
    });
  } catch (error) {
    console.error('API Route Error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}
```

### POST Route Template

```typescript
// src/app/api/orders/route.ts

import { NextRequest, NextResponse } from 'next/server';
import { createOrder } from '@/services/orderServices';
import { OrderCreateSchema } from '@/types/order';

export async function POST(request: NextRequest) {
  try {
    // Parse request body
    const body = await request.json();

    // Validate request body (using Zod or manual validation)
    const validation = OrderCreateSchema.safeParse(body);
    if (!validation.success) {
      return NextResponse.json(
        { error: 'Invalid request body', details: validation.error.flatten() },
        { status: 400 }
      );
    }

    // Call service layer
    const result = await createOrder(validation.data);

    if (!result.success) {
      return NextResponse.json(
        { error: result.error },
        { status: 400 }
      );
    }

    // Return success response
    return NextResponse.json(
      { order: result.data },
      { status: 201 }
    );
  } catch (error) {
    console.error('API Route Error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}
```

