### Creating a Service File

Every service file follows this structure:

```typescript
// src/services/productServices.ts

import { API_ENDPOINTS } from '@/constants/apiEndpoints';
import type { Product, ProductsResponse } from '@/types/product';

/**
 * Fetches all products with pagination
 * @param page - Page number (1-indexed)
 * @param perPage - Items per page
 * @returns ProductsResponse with items and pagination info
 */
export const fetchProducts = async (
  page: number = 1,
  perPage: number = 12
): Promise<ProductsResponse> => {
  try {
    const response = await fetch(
      `${API_ENDPOINTS.PRODUCTS}?page=${page}&per_page=${perPage}`,
      {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
        next: { revalidate: 3600 }, // ISR: revalidate every hour
      }
    );

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const data = await response.json();

    return {
      items: data.products || [],
      totalPages: parseInt(response.headers.get('X-WP-TotalPages') || '1'),
      totalItems: parseInt(response.headers.get('X-WP-Total') || '0'),
    };
  } catch (error) {
    console.error('Error fetching products:', error);
    return {
      items: [],
      totalPages: 0,
      totalItems: 0,
    };
  }
};

/**
 * Fetches a single product by slug
 * @param slug - Product URL slug
 * @returns Product or null if not found
 */
export const fetchProductBySlug = async (
  slug: string
): Promise<Product | null> => {
  try {
    const response = await fetch(
      `${API_ENDPOINTS.PRODUCTS}?slug=${slug}`,
      {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
        next: { revalidate: 3600 },
      }
    );

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const data = await response.json();
    return data[0] || null;
  } catch (error) {
    console.error(`Error fetching product with slug "${slug}":`, error);
    return null;
  }
};
```

### Error Handling Template

**The Golden Rule:** Services should never throw errors that crash the UI. Return safe defaults.

```typescript
export const fetchResource = async (): Promise<ResourceResponse> => {
  try {
    const response = await fetch(API_ENDPOINT);

    if (!response.ok) {
      // Log for debugging, but don't crash
      console.error(`API Error: ${response.status} ${response.statusText}`);
      return { items: [], error: `Failed to fetch: ${response.status}` };
    }

    const data = await response.json();

    // Validate response structure
    if (!data || !Array.isArray(data.items)) {
      console.error('Invalid response structure:', data);
      return { items: [], error: 'Invalid response format' };
    }

    return { items: data.items, error: null };
  } catch (error) {
    // Network errors, JSON parse errors, etc.
    console.error('Service error:', error);
    return { 
      items: [], 
      error: error instanceof Error ? error.message : 'Unknown error' 
    };
  }
};
```

### GET Route Template

```typescript
// src/app/api/products/route.ts

import { NextRequest, NextResponse } from 'next/server';
import { fetchProducts } from '@/services/productServices';

export async function GET(request: NextRequest) {
  try {
    // Extract query parameters
    const searchParams = request.nextUrl.searchParams;
    const page = parseInt(searchParams.get('page') || '1');
    const perPage = parseInt(searchParams.get('per_page') || '12');
    const category = searchParams.get('category') || undefined;

    // Validate parameters
    if (page < 1 || perPage < 1 || perPage > 100) {
      return NextResponse.json(
        { error: 'Invalid pagination parameters' },
        { status: 400 }
      );
    }

    // Call service layer
    const result = await fetchProducts(page, perPage, category);

    // Return response with cache headers
    return NextResponse.json(result, {
      headers: {
        'Cache-Control': 'public, s-maxage=3600, stale-while-revalidate=86400',
      },
    });
  } catch (error) {
    console.error('API Route Error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}
```

### Route Protection

> **File-name note (version-sensitive):** Next.js 16 kits wire this via **`src/proxy.ts`** (the kit's current convention — see AUTH_MANUAL's middleware section); earlier versions use `src/middleware.ts` as shown below. **Verify which file your repo uses on disk (recon Q2.5)** — the pattern is the same, the filename is not.

```typescript
// src/middleware.ts (src/proxy.ts on Next 16 kits — see note above)

import { createServerClient } from '@supabase/ssr';
import { NextResponse, type NextRequest } from 'next/server';

export async function middleware(request: NextRequest) {
  const response = NextResponse.next();

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll: () => request.cookies.getAll(),
        setAll: (cookies) => {
          cookies.forEach(({ name, value, options }) => {
            response.cookies.set(name, value, options);
          });
        },
      },
    }
  );

  const { data: { user } } = await supabase.auth.getUser();

  // Protect admin routes
  if (request.nextUrl.pathname.startsWith('/admin')) {
    if (!user) {
      return NextResponse.redirect(new URL('/auth/login', request.url));
    }

    // Check admin role
    const role = user.user_metadata?.role;
    if (role !== 'admin' && role !== 'superadmin') {
      return NextResponse.redirect(new URL('/', request.url));
    }
  }

  // Protect customer routes
  if (request.nextUrl.pathname.startsWith('/customer')) {
    if (!user) {
      return NextResponse.redirect(new URL('/auth/login', request.url));
    }
  }

  return response;
}

export const config = {
  matcher: [
    '/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)',
  ],
};
```

