### Cart Store Pattern

```typescript
// src/store/useCartStore.ts

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

interface CartItem {
  id: string;
  productId: number;
  variationId?: number;
  name: string;
  price: number;
  quantity: number;
  image?: string;
}

interface CartState {
  items: CartItem[];
  hasHydrated: boolean;

  addItem: (item: Omit<CartItem, 'id'>) => void;
  removeItem: (id: string) => void;
  updateQuantity: (id: string, quantity: number) => void;
  clearCart: () => void;
  setHasHydrated: (value: boolean) => void;
}

const generateId = (item: Omit<CartItem, 'id'>) =>
  `${item.productId}-${item.variationId || 'default'}`;

export const useCartStore = create<CartState>()(
  persist(
    (set) => ({
      items: [],
      hasHydrated: false,

      addItem: (item) =>
        set((state) => {
          const id = generateId(item);
          const existing = state.items.find((i) => i.id === id);

          if (existing) {
            return {
              items: state.items.map((i) =>
                i.id === id ? { ...i, quantity: i.quantity + item.quantity } : i
              ),
            };
          }

          return { items: [...state.items, { ...item, id }] };
        }),

      removeItem: (id) =>
        set((state) => ({
          items: state.items.filter((item) => item.id !== id),
        })),

      updateQuantity: (id, quantity) =>
        set((state) => ({
          items: quantity > 0
            ? state.items.map((item) =>
                item.id === id ? { ...item, quantity } : item
              )
            : state.items.filter((item) => item.id !== id),
        })),

      clearCart: () => set({ items: [] }),
      setHasHydrated: (hasHydrated) => set({ hasHydrated }),
    }),
    {
      name: 'cart-storage',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({ items: state.items }),
      onRehydrateStorage: () => (state) => {
        state?.setHasHydrated(true);
      },
    }
  )
);

// Selectors
export const selectCartItems = (state: CartState) => state.items;
export const selectCartItemCount = (state: CartState) =>
  state.items.reduce((sum, item) => sum + item.quantity, 0);
export const selectCartSubtotal = (state: CartState) =>
  state.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
export const selectHasHydrated = (state: CartState) => state.hasHydrated;
```

**Synchronization Logic:**

```typescript
// When creating a user in Supabase Auth (protected admin channel)
const createUserWithProfile = async (email: string, password: string, profile: UserProfile) => {
  // 1. Create in Supabase Auth. The role rides user_metadata ONLY as the
  //    creation-time transport — the kit's handle_new_user() trigger applies
  //    it into user_roles. It is never read back for authorization.
  const { data: authData, error: authError } = await supabase.auth.admin.createUser({
    email,
    password,
    email_confirm: true,
    user_metadata: {
      display_name: profile.displayName,
      role: profile.role, // transport for the trigger, not storage
    },
  });

  if (authError) throw authError;

  // 2. Create the profile mirror row with the SAME ID — no role column here;
  //    user_roles was populated by the trigger in step 1.
  const { error: profileError } = await supabase
    .from('app_users')
    .insert({
      id: authData.user.id, // Same UUID
      display_name: profile.displayName,
    });

  if (profileError) {
    // Rollback: delete auth user
    await supabase.auth.admin.deleteUser(authData.user.id);
    throw profileError;
  }

  return authData.user;
};
