    const supabase = await createClient();

    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .single();

    if (error) {
      console.error('Supabase error fetching profile:', error);
      return { data: null, error: error.message };
    }

    return { data, error: null };
  } catch (error) {
    console.error('Service error:', error);
    return { data: null, error: 'Failed to fetch profile' };
  }
};

/**
 * Updates a user profile
 * Server-side only
 */
export const updateProfile = async (
  userId: string,
  updates: ProfileUpdate
): Promise<{ data: Profile | null; error: string | null }> => {
  try {
    const supabase = await createClient();

    const { data, error } = await supabase
      .from('profiles')
      .update(updates)
      .eq('id', userId)
      .select()
      .single();

    if (error) {
      console.error('Supabase error updating profile:', error);
      return { data: null, error: error.message };
    }

    return { data, error: null };
  } catch (error) {
    console.error('Service error:', error);
    return { data: null, error: 'Failed to update profile' };
  }
};

/**
 * Fetches records with pagination
 * Demonstrates the standard pagination pattern
 */
export const fetchPaginatedRecords = async <T extends keyof Tables>(
  table: T,
  options: {
    page?: number;
    perPage?: number;
    orderBy?: string;
    ascending?: boolean;
    filters?: Record<string, unknown>;
  } = {}
): Promise<{
  data: Tables[T]['Row'][];
  count: number;
  error: string | null;
}> => {
  const { page = 1, perPage = 10, orderBy = 'created_at', ascending = false, filters = {} } = options;

  try {
    const supabase = await createClient();

    // Calculate range for pagination
    const from = (page - 1) * perPage;
    const to = from + perPage - 1;

    let query = supabase
      .from(table)
      .select('*', { count: 'exact' })
      .order(orderBy, { ascending })
      .range(from, to);

    // Apply filters
    Object.entries(filters).forEach(([key, value]) => {
      if (value !== undefined && value !== null) {
        query = query.eq(key, value);
      }
    });

    const { data, count, error } = await query;

    if (error) {
      console.error(`Supabase error fetching ${table}:`, error);
      return { data: [], count: 0, error: error.message };
    }

    return { data: data || [], count: count || 0, error: null };
  } catch (error) {
    console.error('Service error:', error);
    return { data: [], count: 0, error: 'Failed to fetch records' };
  }
};
